  eanUpc: text('ean_upc').notNull().unique(),
  itemNumber: text('item_number'),
  brand: text('brand'),
  model: text('model'),
  name: text('name').notNull(),
  description: text('description'),
  costPriceNet: integer('cost_price_net', { mode: 'number' }), // ex-tax cents (from Inkoop ÷ 1.21 × 100)
  sellPriceNet: integer('sell_price_net', { mode: 'number' }).notNull(), // ex-tax cents (from Verkoopprijs ÷ 1.21 × 100)
  vatRateBasisPoints: integer('vat_rate_basis_points').notNull().default(2100),
  imageUrl: text('image_url'),
  category: text('category'),
  color: text('color'),
